import 'package:flutter/material.dart';
import '../api.dart';
class PetQrScreen extends StatefulWidget { const PetQrScreen({super.key, required this.petId}); final String petId; @override State<PetQrScreen> createState() => _PetQrScreenState(); }
class _PetQrScreenState extends State<PetQrScreen> { final api = JopetsApi(); String? qr; String? error; @override void initState() { super.initState(); load(); } Future<void> load() async { try { final value = await api.petQr(widget.petId); if (mounted) setState(() => qr = value); } catch (e) { if (mounted) setState(() => error = e.toString()); } } @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('Código de verificación')), body: Center(child: error != null ? Text(error!, textAlign: TextAlign.center) : qr == null ? const CircularProgressIndicator() : Column(mainAxisAlignment: MainAxisAlignment.center, children: [const Icon(Icons.qr_code_2, size: 220), const SizedBox(height: 20), SelectableText(qr!, textAlign: TextAlign.center), const SizedBox(height: 12), const Text('Código emitido por el servidor', textAlign: TextAlign.center)]))); }
